    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_ElwMstReq').set('method', 'elwPageSearch');
    await moveUrl('/list/elwPage.do', {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.elwExcelUploadPop
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.elwExcelUploadPop = async function () {
    /* sdd-asis-lifecycle:begin fn_ElwExcelUploadPop — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let i = 0;
    i++;
    const popName = "pop_excelUpload_" + i;
    if (scwin.getCookie(popName) !== popName) {
        $c.win.openPopup('', String('' || '').split(',').reduce(function (o, kv) { const p = kv.split('='); const k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, (typeof popName !== 'undefined' ? popName : '') ? Object.assign({ scrollbars: false, resizable: true, width: "500", height: "500", type: "pageFramePopup" }, { id: (typeof popName !== 'undefined' ? popName : '') }) : { scrollbars: false, resizable: true, width: "500", height: "500", type: "pageFramePopup" }), {});
        (document.excelUploadForm || { elements: [] }).target = popName;
        (document.excelUploadForm || { elements: [] }).action = "/list/elwPageUpload.do?method=elwExcelUploadPop";
        (document.excelUploadForm || { elements: [] }).method = "post";
        await scwin.tx_fn_ElwExcelUploadPop();
    }
    /* sdd-asis-lifecycle:end */
};


