*/
scwin.getCookie = function (Name) { const v = $c.util.getSessionStorage(Name); return (v === undefined || v === null) ? '' : v; };



/**
 * @event
 * @name scwin.krxpage_pagenavigator_90_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_90_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_ElwMstReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_90.page' }); } scwin.search(); };
